    return bounds is None or bounds[0] <= version <= bounds[1]


def is_acyclic(graph):
    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True

        state[node] = 1
        for neighbor in graph.get(node, ()):
            if not visit(neighbor):
                return False
        state[node] = 2
        return True

    for node in graph:
        if not visit(node):
            return False
    return True
